import Blockly from 'blockly/core';
import 'blockly/blocks';
import { pythonGenerator } from 'blockly/python';

const classMutator = {
  mutationToDom: function() {
    var container = Blockly.utils.xml.createElement('mutation');
    container.setAttribute('items', this.itemCount_);
    return container;
  },

  domToMutation: function(xmlElement) {
    this.itemCount_ = parseInt(xmlElement.getAttribute('items'), 10);
    this.updateShape_();
  },

  decompose: function(workspace) {
    var containerBlock = workspace.newBlock('class_create_container');
    containerBlock.initSvg();
    var connection = containerBlock.getInput('STACK').connection;
    for (var i = 0; i < this.itemCount_; i++) {
      var itemBlock = workspace.newBlock('class_create_method');
      itemBlock.initSvg();
      connection.connect(itemBlock.previousConnection);
      connection = itemBlock.nextConnection;
    }
    return containerBlock;
  },

  compose: function(containerBlock) {
    var itemBlock = containerBlock.getInputTargetBlock('STACK');
    var connections = [];
    var nameConnections = [];
    while (itemBlock && !itemBlock.isInsertionMarker()) {
      connections.push(itemBlock.valueConnection_);
      nameConnections.push(itemBlock.nameConnection_);
      itemBlock = itemBlock.nextConnection &&
          itemBlock.nextConnection.targetBlock();
    }
    this.itemCount_ = connections.length;
    this.updateShape_();
    for (var i = 0; i < this.itemCount_; i++) {
      if (nameConnections[i]) {
        this.getInput('NAME' + i).connection.connect(nameConnections[i]);
      }
      if (connections[i]) {
        this.getInput('CODE' + i).connection.connect(connections[i]);
      }
    }
  },

  saveConnections: function(containerBlock) {
    var itemBlock = containerBlock.getInputTargetBlock('STACK');
    var i = 0;
    while (itemBlock) {
      var nameInput = this.getInput('NAME' + i);
      var codeInput = this.getInput('CODE' + i);
      itemBlock.nameConnection_ = nameInput && nameInput.connection.targetConnection;
      itemBlock.valueConnection_ = codeInput && codeInput.connection.targetConnection;
      i++;
      itemBlock = itemBlock.nextConnection &&
          itemBlock.nextConnection.targetBlock();
    }
  }
};

Blockly.Blocks['class_create'] = {
  init: function() {
    this.appendDummyInput()
        .appendField('class')
        .appendField(new Blockly.FieldTextInput('MyClass'), 'CLASS_NAME');
    this.setColour("#c70303");
    this.setTooltip('Create a class with methods');
    this.setDeletable(true);
    this.setMovable(true);
    
    // Initialize with one method
    this.methodCount_ = 1;
    this.updateShape_();

    // Set up the mutator
    this.setMutator(new Blockly.icons.MutatorIcon(['method_item'], this));
  },

  saveExtraState: function() {
    return {
      'methodCount': this.methodCount_
    };
  },

  loadExtraState: function(state) {
    this.methodCount_ = state['methodCount'];
    this.updateShape_();
  },

  decompose: function(workspace) {
    const containerBlock = workspace.newBlock('method_container');
    containerBlock.initSvg();
    let connection = containerBlock.getInput('STACK').connection;
    
    for (let i = 0; i < this.methodCount_; i++) {
      const itemBlock = workspace.newBlock('method_item');
      itemBlock.initSvg();
      connection.connect(itemBlock.previousConnection);
      connection = itemBlock.nextConnection;
    }
    
    return containerBlock;
  },

  compose: function(containerBlock) {
    let itemBlock = containerBlock.getInputTargetBlock('STACK');
    const connections = [];
    const names = [];
    
    while (itemBlock && !itemBlock.isInsertionMarker()) {
      connections.push(itemBlock.valueConnection_);
      names.push(itemBlock.getFieldValue('METHOD_NAME'));
      itemBlock = itemBlock.nextConnection && itemBlock.nextConnection.targetBlock();
    }
    
    this.methodCount_ = connections.length;
    this.updateShape_();
    
    // Reconnect blocks and restore names
    for (let i = 0; i < this.methodCount_; i++) {
      if (connections[i]) {
        this.getInput('METHOD' + i).connection.connect(connections[i]);
      }
      if (names[i]) {
        this.setFieldValue(names[i], 'METHOD_NAME' + i);
      }
    }
  },

  saveConnections: function(containerBlock) {
    let itemBlock = containerBlock.getInputTargetBlock('STACK');
    let i = 0;
    while (itemBlock) {
      const input = this.getInput('METHOD' + i);
      itemBlock.valueConnection_ = input && input.connection.targetConnection;
      itemBlock = itemBlock.nextConnection && itemBlock.nextConnection.targetBlock();
      i++;
    }
  },

  updateShape_: function() {
    // Remove any existing METHOD inputs
    for (let i = 0; i < this.methodCount_; i++) {
      if (this.getInput('METHOD' + i)) {
        this.removeInput('METHOD' + i);
      }
    }

    // Add new METHOD inputs
    for (let i = 0; i < this.methodCount_; i++) {
      this.appendStatementInput('METHOD' + i)
        .setCheck(null)
        .appendField('def')
        .appendField(new Blockly.FieldTextInput('method' + (i + 1)), 'METHOD_NAME' + i);
    }
  }
};

Object.assign(Blockly.Blocks['class_create'], classMutator);

Blockly.Blocks['class_create_container'] = {
  init: function() {
    this.setColour(360);
    this.appendDummyInput()
        .appendField('class');
    this.appendStatementInput('STACK');
    this.setTooltip('Add, remove, or reorder methods to reconfigure this class');
    this.contextMenu = false;
  }
};

Blockly.Blocks['class_create_method'] = {
  init: function() {
    this.setColour(360);
    this.appendDummyInput()
        .appendField('method');
    this.setPreviousStatement(true);
    this.setNextStatement(true);
    this.setTooltip('Add a method to the class');
    this.contextMenu = false;
  }
};

pythonGenerator.forBlock['class_create'] = function(block) {
  var className = block.getFieldValue('CLASS_NAME') || 'MyClass';
  var methods = [];
  for (var i = 0; i < block.methodCount_; i++) {
    var methodName = block.getFieldValue('METHOD_NAME' + i) || 'method' + (i + 1);
    var methodCode = pythonGenerator.statementToCode(block, 'METHOD' + i) || pythonGenerator.PASS;
    methods.push('def ' + methodName + '(self):\n' + methodCode);
  }
  var code = 'class ' + className + ':\n' + methods.join('\n');
  return [code, pythonGenerator.ORDER_NONE];
};

Blockly.Blocks['class_get'] = {
  init: function() {
    this.appendValueInput('INSTANCE')
        .setCheck(null)
        .appendField('get attribute');
    this.appendValueInput('ATTRIBUTE')
        .setCheck('String')
        .appendField('from instance');
    this.setOutput(true, null);
    this.setColour(160);
    this.setTooltip('Get an attribute value from a class instance');
  }
};

pythonGenerator.forBlock['class_get'] = function(block) {
  const instance = pythonGenerator.valueToCode(block, 'INSTANCE', pythonGenerator.ORDER_MEMBER) || 'instance';
  const attribute = pythonGenerator.valueToCode(block, 'ATTRIBUTE', pythonGenerator.ORDER_ATOMIC) || "'attribute'";
  return [`${instance}.${attribute}`, pythonGenerator.ORDER_MEMBER];
};

Blockly.Blocks['class_set'] = {
  init: function() {
    this.appendValueInput('INSTANCE')
        .setCheck(null)
        .appendField('set attribute');
    this.appendValueInput('ATTRIBUTE')
        .setCheck('String')
        .appendField('in instance');
    this.appendValueInput('VALUE')
        .setCheck(null)
        .appendField('to');
    this.setPreviousStatement(true, null);
    this.setNextStatement(true, null);
    this.setColour(160);
    this.setTooltip('Set an attribute value in a class instance');
  }
};

pythonGenerator.forBlock['class_set'] = function(block) {
  const instance = pythonGenerator.valueToCode(block, 'INSTANCE', pythonGenerator.ORDER_MEMBER) || 'instance';
  const attribute = pythonGenerator.valueToCode(block, 'ATTRIBUTE', pythonGenerator.ORDER_ATOMIC) || "'attribute'";
  const value = pythonGenerator.valueToCode(block, 'VALUE', pythonGenerator.ORDER_ATOMIC) || 'None';
  return `${instance}.${attribute} = ${value}\n`;
};
